/// <summary>
/// CB223_PalletRounding
/// Represents the ordered list of enumeration values for <c>METCustomerGroupAll</c> enum.
/// Allows to add values to the list to support extension.
/// </summary>
public class METPalletRoundingPolicyPartyCodeTypeOrderedList implements Enumerable
{
    List palletRoundingPolicyPartyCodeTypeOrderedList;

}

Method.Source:
/// <summary>
/// Get the enumerator of the ordered list.
/// </summary>
/// <returns>An instance of <c>ListEnumerator</c> class.</returns>
public Enumerator getEnumerator()
{
    return palletRoundingPolicyPartyCodeTypeOrderedList.getEnumerator();
}

/// <summary>
/// _palletRoundingPolicyHeader
/// </summary>
/// <param name = "_all">Specify if All customers</param>
protected void new(boolean _all)
{
    palletRoundingPolicyPartyCodeTypeOrderedList = new List(Types::Enum);

    this.initializePalletRoundingPolicyPartyCodeTypeOrderedList(_all);
}

/// <summary>
/// Set list in ascending or descending order
/// </summary>
/// <param name = "_enumerateInOrder">Ascending or descending order</param>
private void setEnumerateInOrder(SortOrder _enumerateInOrder)
{
    if (_enumerateInOrder == SortOrder::Descending)
    {
        this.reverseOrderedList();
    }
}

/// <summary>
/// Reverse the ordered list
/// </summary>
private void reverseOrderedList()
{
    List reversedPalletRoundingPolicyPartyCodeTypeOrderedList = new List(Types::Enum);
    ListEnumerator enumerator = this.getEnumerator() as ListEnumerator;

    while (enumerator.moveNext())
    {
        reversedPalletRoundingPolicyPartyCodeTypeOrderedList.addStart(enumerator.current());
    }

    palletRoundingPolicyPartyCodeTypeOrderedList = reversedPalletRoundingPolicyPartyCodeTypeOrderedList;
}

/// <summary>
/// Constructs a new instance of the <c>METPalletRoundingPolicyPartyCodeTypeOrderedList</c> class to be enumerated in the specified order.
/// </summary>
/// <param name = "_all">Specify if All customers</param>
/// <param name="_enumerateInOrder">Enumerate the values in the enum in the specified order.</param>
/// <returns>An instance of <c>METPalletRoundingPolicyPartyCodeTypeOrderedList</c> class.</returns>
public static METPalletRoundingPolicyPartyCodeTypeOrderedList newFromOrder(boolean _all, SortOrder _enumerateInOrder = SortOrder::Ascending)
{
    METPalletRoundingPolicyPartyCodeTypeOrderedList orderedList = new METPalletRoundingPolicyPartyCodeTypeOrderedList(_all);
    orderedList.setEnumerateInOrder(_enumerateInOrder);
    return orderedList;
}

/// <summary>
/// Initialize the list with all the applicable values of <c>METCustomerGroupAll</c> enumeration in ascending order.
/// For priority 1-4, use Table and GroupId
/// For priority 5-6, use All
/// </summary>
/// <param name = "_all">Specify if All customers</param>
protected void initializePalletRoundingPolicyPartyCodeTypeOrderedList(boolean _all)
{
    // based on the pallet rounding priority for customer specification
    if (_all)
    {
        palletRoundingPolicyPartyCodeTypeOrderedList.addEnd(METCustomerGroupAll::All);
    }
    else
    {
        palletRoundingPolicyPartyCodeTypeOrderedList.addEnd(METCustomerGroupAll::Table);
        palletRoundingPolicyPartyCodeTypeOrderedList.addEnd(METCustomerGroupAll::GroupId);
    }
}
